from dataclasses import dataclass

from .errors import EvalError

OPERATORS = "+-*/%^()"


@dataclass(frozen=True)
class Token:
    kind: str  # "INT", "OP", or "EOF"
    value: str
    pos: int


def tokenize(text: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            start = i
            while i < n and text[i].isdigit():
                i += 1
            tokens.append(Token("INT", text[start:i], start))
            continue
        if ch in OPERATORS:
            tokens.append(Token("OP", ch, i))
            i += 1
            continue
        raise EvalError(f"syntax error: unexpected character {ch!r} at {i}")
    tokens.append(Token("EOF", "", n))
    return tokens
"""Recursive-descent parser producing a tiny tuple-based AST.

AST nodes:
    ("num", int)
    ("neg", node)
    ("bin", op, left, right)
"""

from .errors import EvalError
from .lexer import Token, tokenize


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def accept(self, *ops: str) -> Token | None:
        tok = self.peek()
        if tok.kind == "OP" and tok.value in ops:
            return self.advance()
        return None

    def expect(self, op: str) -> Token:
        tok = self.accept(op)
        if tok is None:
            got = self.peek().value or "end of input"
            raise EvalError(f"syntax error: expected {op!r}, got {got!r}")
        return tok

    def parse(self):
        node = self.expr()
        if self.peek().kind != "EOF":
            raise EvalError(f"syntax error: unexpected {self.peek().value!r}")
        return node

    def expr(self):
        node = self.term()
        while (tok := self.accept("+", "-")) is not None:
            node = ("bin", tok.value, node, self.term())
        return node

    def term(self):
        node = self.power()
        while (tok := self.accept("*", "/", "%")) is not None:
            node = ("bin", tok.value, node, self.power())
        return node

    def power(self):
        node = self.unary()
        while self.accept("^") is not None:
            node = ("bin", "^", node, self.unary())
        return node

    def unary(self):
        if self.accept("-") is not None:
            return ("neg", self.unary())
        if self.accept("+") is not None:
            return self.unary()
        return self.atom()

    def atom(self):
        tok = self.peek()
        if tok.kind == "INT":
            self.advance()
            return ("num", int(tok.value))
        if self.accept("(") is not None:
            node = self.expr()
            self.expect(")")
            return node
        got = tok.value or "end of input"
        raise EvalError(f"syntax error: unexpected {got!r}")


def parse(text: str):
    return Parser(tokenize(text)).parse()
from .errors import EvalError
from .parser import parse


def _apply(op: str, a: int, b: int) -> int:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return a // b
    if op == "%":
        return a % b
    if op == "^":
        return a**b
    raise EvalError(f"unknown operator {op!r}")


def _eval(node) -> int:
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "neg":
        return -_eval(node[1])
    if kind == "bin":
        _, op, left, right = node
        return _apply(op, _eval(left), _eval(right))
    raise EvalError(f"bad node {kind!r}")


def evaluate(text: str) -> int:
    """Evaluate an integer expression string."""
    return _eval(parse(text))
class EvalError(Exception):
    """Raised when an expression cannot be parsed or evaluated."""
